CREATE SEQUENCE IF NOT EXISTS seq_dummy START 1;
CREATE TABLE IF NOT EXISTS sources(source_id VARCHAR PRIMARY KEY, family VARCHAR, endpoint VARCHAR, source_tier VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS source_runs(source_run_id VARCHAR PRIMARY KEY, source_id VARCHAR, status VARCHAR, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, result_count BIGINT, failure_type VARCHAR, failure_packet_json VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS entities(entity_id VARCHAR PRIMARY KEY, legal_name VARCHAR NOT NULL, normalized_name VARCHAR NOT NULL, entity_type VARCHAR, jurisdiction VARCHAR, identity_status VARCHAR, formed_date DATE, dissolved_date DATE, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, observed_at TIMESTAMPTZ NOT NULL, superseded_at TIMESTAMPTZ, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, review_status VARCHAR, supersedes_record_id VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS entity_aliases(alias_id VARCHAR PRIMARY KEY, entity_id VARCHAR, alias VARCHAR, normalized_alias VARCHAR, alias_type VARCHAR, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, observed_at TIMESTAMPTZ, superseded_at TIMESTAMPTZ, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, review_status VARCHAR, supersedes_record_id VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS entity_identifiers(identifier_id VARCHAR PRIMARY KEY, entity_id VARCHAR, identifier_type VARCHAR, identifier_value VARCHAR, jurisdiction VARCHAR, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, observed_at TIMESTAMPTZ, superseded_at TIMESTAMPTZ, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, review_status VARCHAR, supersedes_record_id VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS entity_relationships(relationship_id VARCHAR PRIMARY KEY, parent_entity_id VARCHAR, child_entity_id VARCHAR, relationship_type VARCHAR, ownership_percent DOUBLE, transaction_type VARCHAR, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, observed_at TIMESTAMPTZ, superseded_at TIMESTAMPTZ, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, review_status VARCHAR, supersedes_record_id VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS awards(award_key VARCHAR PRIMARY KEY, award_id VARCHAR, piid VARCHAR, parent_award_id VARCHAR, jurisdiction VARCHAR, issuing_entity_id VARCHAR, contractor_entity_id VARCHAR, recipient_entity_id VARCHAR, awarding_subagency VARCHAR, base_contract_number VARCHAR, amendment_identifier VARCHAR, amount_type VARCHAR, amount_delta DECIMAL(20,2), cumulative_authorized_value DECIMAL(20,2), obligated_amount DECIMAL(20,2), paid_amount DECIMAL(20,2), ceiling_amount DECIMAL(20,2), description VARCHAR, place_of_performance VARCHAR, signed_date DATE, start_date DATE, end_date DATE, owner_at_award VARCHAR, current_owner VARCHAR, novation_status VARCHAR, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, observed_at TIMESTAMPTZ, superseded_at TIMESTAMPTZ, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, review_status VARCHAR, supersedes_record_id VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS award_transactions(transaction_key VARCHAR PRIMARY KEY, award_key VARCHAR, transaction_id VARCHAR, transaction_type VARCHAR, action_date DATE, amount_delta DECIMAL(20,2), obligation_delta DECIMAL(20,2), description VARCHAR, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, observed_at TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS subawards(subaward_key VARCHAR PRIMARY KEY, award_key VARCHAR, prime_entity_id VARCHAR, sub_entity_id VARCHAR, tier_level INTEGER, amount DECIMAL(20,2), action_date DATE, scope VARCHAR, affiliate_status VARCHAR, self_subcontract BOOLEAN, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, observed_at TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payments(payment_key VARCHAR PRIMARY KEY, award_key VARCHAR, payee_entity_id VARCHAR, payment_date DATE, amount DECIMAL(20,2), payment_type VARCHAR, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, observed_at TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS projects(project_id VARCHAR PRIMARY KEY, project_name VARCHAR, municipality VARCHAR, facility_id VARCHAR, pw_number VARCHAR, disaster_number VARCHAR, program VARCHAR, status VARCHAR, source_id VARCHAR, source_run_id VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, observed_at TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS project_award_bridges(bridge_id VARCHAR PRIMARY KEY, project_id VARCHAR, award_key VARCHAR, contractor_role VARCHAR, bridge_method VARCHAR, bridge_confidence DOUBLE, source_id VARCHAR, source_run_id VARCHAR, observed_at TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS evidence(evidence_key VARCHAR PRIMARY KEY, subject_id VARCHAR, predicate VARCHAR, object_json VARCHAR, source_hash VARCHAR, source_locator VARCHAR, claim_text VARCHAR, evidence_tier VARCHAR, confidence DOUBLE, observed_at TIMESTAMPTZ, review_status VARCHAR, contradiction_group VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS contradictions(contradiction_id VARCHAR PRIMARY KEY, claim_a_evidence_key VARCHAR, claim_b_evidence_key VARCHAR, likely_cause VARCHAR, controlling_source VARCHAR, resolution_status VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS gaps(gap_id VARCHAR PRIMARY KEY, subject_id VARCHAR, domain VARCHAR, gap_status VARCHAR, description VARCHAR, recovery_route VARCHAR, priority DOUBLE, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS query_history(query_id VARCHAR PRIMARY KEY, query_key VARCHAR, source_id VARCHAR, entity_id VARCHAR, project_id VARCHAR, query_type VARCHAR, parameters_json VARCHAR, parameters_hash VARCHAR, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, status VARCHAR, result_count BIGINT, new_record_count BIGINT, updated_record_count BIGINT, null_result BOOLEAN, failure_type VARCHAR, fallback_route VARCHAR, retry_after TIMESTAMPTZ, fresh_until TIMESTAMPTZ, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_query_key ON query_history(query_key);
CREATE TABLE IF NOT EXISTS coverage_state(entity_id VARCHAR, domain VARCHAR, required_items BIGINT, resolved_weight DOUBLE, public_data_coverage DOUBLE, resolvable_coverage DOUBLE, domain_confidence DOUBLE, blockers_json VARCHAR, next_actions_json VARCHAR, updated_at TIMESTAMPTZ, PRIMARY KEY(entity_id, domain));
CREATE TABLE IF NOT EXISTS entity_priority_queue(entity_id VARCHAR PRIMARY KEY, current_rank INTEGER, previous_rank INTEGER, rank_delta INTEGER, priority_score DOUBLE, coverage_deficit DOUBLE, last_researched_at TIMESTAMPTZ, staleness_score DOUBLE, priority_reasons_json VARCHAR, highest_value_next_action VARCHAR, estimated_recovery_gain DOUBLE, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS skill_improvement_proposals(proposal_id VARCHAR PRIMARY KEY, trigger_run_id VARCHAR, trigger_entity_id VARCHAR, problem_type VARCHAR, problem VARCHAR, evidence_ids_json VARCHAR, current_behavior VARCHAR, proposed_generalized_change VARCHAR, affected_sections_json VARCHAR, required_tests_json VARCHAR, expected_coverage_gain DOUBLE, expected_requery_reduction DOUBLE, regression_risk VARCHAR, status VARCHAR, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS skill_validation_runs(validation_run_id VARCHAR PRIMARY KEY, candidate_version VARCHAR, case_id VARCHAR, passed BOOLEAN, metrics_json VARCHAR, failures_json VARCHAR, run_at TIMESTAMPTZ);
